/// Runs `git <prefix> <paths...>` in `root` with each path matched literally, mapping a non-zero exit to
/// `GraphError::Command`.
fn run_git_on_paths<R: CommandRunner>(
    runner: &R,
    root: &Path,
    prefix: &[&str],
    paths: &[&PathBuf],
) -> Result<(), GraphError> {
    let rendered: Vec<Pathspec> = paths.iter().map(|p| Pathspec::literal(p)).collect();
    let mut args: Vec<&str> = prefix.to_vec();
    args.extend(rendered.iter().map(Pathspec::as_str));
    let output = runner.run("git", &args, root)?;
    if !output.success() {
        return Err(GraphError::Command(CommandError::Failed {
            program: "git".to_string(),
            exit_code: output.exit_code,
            stderr: output.redacted_stderr(),
        }));
    }
    Ok(())
}

